@@ -2867,0 +2867,10 @@
+// 12 bit signed value that is non-negative, i.e. 0 <= value <= 2047.
+operand immI_simm12NonNeg()
+%{
+  predicate(Assembler::is_simm12((int64_t)n->get_int()) && n->get_int() >= 0);
+  match(ConI);
+  op_cost(0);
+  format %{ %}
+  interface(CONST_INTER);
+%}
+
@@ -9031,0 +9041,17 @@
+// With a non-negative mask the 64-bit AND drops the high half itself, so the L2I
+// is redundant.
+instruct convI2L_andI_l2i_reg_imm(iRegLNoSp dst, iRegL src, immI_simm12NonNeg mask) %{
+  match(Set dst (ConvI2L (AndI (ConvL2I src) mask)));
+
+  ins_cost(ALU_COST);
+  format %{ "andi  $dst, $src, $mask\t#@convI2L_andI_l2i_reg_imm" %}
+
+  ins_encode %{
+    __ andi(as_Register($dst$$reg),
+            as_Register($src$$reg),
+            (int32_t)($mask$$constant));
+  %}
+
+  ins_pipe(ialu_reg_imm);
+%}
+

